def transform(grid):
    """Extend vertical rays upward, changing color at matching horizontal bars."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # The short vertical color markers are placed at the bottom of the grid.
    marker_cols = [c for c in range(w) if any(g[r][c] for r in range(max(0, h - 2), h))]
    for c in marker_cols:
        crossings = []
        for r in range(h):
            if g[r][c] != 0:
                continue
            left = next((g[r][x] for x in range(c - 1, -1, -1) if g[r][x]), 0)
            right = next((g[r][x] for x in range(c + 1, w) if g[r][x]), 0)
            if left and left == right:
                crossings.append((r, left))

        # A bar's color runs upward through the space since the previous bar.
        previous = -1
        for r, color in crossings:
            for y in range(previous + 1, r + 1):
                if g[y][c] == 0:
                    g[y][c] = color
            previous = r

        # A single-cell bottom marker also extends upward to the lowest bar;
        # longer bottom stems are preserved as-is.
        bottom_cells = [(y, grid[y][c]) for y in range(h - 1, max(-1, h - 4), -1) if grid[y][c]]
        if len(bottom_cells) == 1 and crossings:
            marker_row, marker_color = bottom_cells[0]
            lowest_bar = max(r for r, _ in crossings)
            for y in range(marker_row - 1, lowest_bar, -1):
                if grid[y][c] == 0 and g[y][c] == 0:
                    g[y][c] = marker_color
    return g

